// Module 2 receives the Module 1 output data (incl. scope_of_supply), client_config and the
// resolved proposal_config (chapter set + the client's clause library + writing rules).
return [{ json: { client_id: $json.client_id, client_config: $json.client_config, proposal_config: $json.proposal_config, data: $json.data } }];

// proposal_only: assemble the document from RFQ + generated content, with NO pricing block.
// email_context is per-request (which thread to reply in) so it travels beside client_config,
// not inside it; Module 4 treats it as optional and falls back to a fresh mail without it.
const m1 = $('Call Module 1').first().json;
const m2 = $('Call Module 2').first().json;
return [{ json: {
  client_id: m1.client_id,
  proposal_config: $('Build Proposal Config').first().json.proposal_config,
  client_config: m1.client_config || null,
  email_context: $('Build Envelope').first().json.email_context || null,
  status: 'ok',
  errors: [],
  data: { rfq: m1.data, content: m2.data, pricing: null }
} }];

// Module 2 receives the Module 1 output data (incl. scope_of_supply), client_config and the
// resolved proposal_config (chapter set + the client's clause library + writing rules).
return [{ json: { client_id: $json.client_id, client_config: $json.client_config, proposal_config: $json.proposal_config, data: $json.data } }];

// Same scope-filtered manual estimate as the pricing_only branch.
const j = $json;
const scope = (j.data && j.data.scope_of_supply) || {};
const ALL_HOURS = { engineering: 40, assembly: 60, commissioning: 20, project_management: 15 };
const GATE = { engineering: scope.engineering, assembly: scope.installation, commissioning: scope.commissioning, project_management: scope.project_management };
const hours_by_category = {};
for (const k of Object.keys(ALL_HOURS)) { if (GATE[k]) hours_by_category[k] = ALL_HOURS[k]; }
const materials_cost = scope.materials ? 5000 : 0;
return [{ json: { client_id: j.client_id, client_config: j.client_config, data: { materials_cost, hours_by_category } } }];

// full_pipeline: assemble from RFQ + generated content + pricing.
const m1 = $('Call Module 1').first().json;
const m2 = $('Call Module 2 (full)').first().json;
const m3 = $('Call Module 3 (full)').first().json;
return [{ json: {
  client_id: m1.client_id,
  proposal_config: $('Build Proposal Config').first().json.proposal_config,
  client_config: m1.client_config || null,
  email_context: $('Build Envelope').first().json.email_context || null,
  status: 'ok',
  errors: [],
  data: { rfq: m1.data, content: m2.data, pricing: m3.data }
} }];

